local UIFeelingMainDialog = Class("UIFeelingMainDialog")
function UIFeelingMainDialog:__init()
    self._time = 3600
    self._cfData = {}
    self.__updateHandle = nil
end

function UIFeelingMainDialog:__delete()
    self._time = nil
    self._cfData = nil
    self.__updateHandle = nil
end

function UIFeelingMainDialog:Awake()
    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
    self.__updateHandle = Bind(self, self.FillTime)
    MonoHelper.AddUpdateListener(self.__updateHandle)

    self:InitData()
    self:FillSelf()
end

--绘制手机上时间那些
function UIFeelingMainDialog:FillTime()
    if self._time >= TIME then
        local weekStr = checkString(WEEKCOMPARE[checkInt(os.date("%w"))])
        local timeStr = checkString(os.date('%H:%M'))
        local month = checkString(os.date('%m'))
        local day = checkString(os.date('%d'))
    
        CfUtils.FillText(self.TxtTime, timeStr)
        CfUtils.FillText(self.TxtWeekDay, weekStr)
        CfUtils.FillText(self.TxtMonthDay, month.."/"..day)
        self.BatteryFill.fillAmount = CS.UnityEngine.SystemInfo.batteryLevel
        self._time = 0
    else
        self._time = self._time + 1
    end
end

function UIFeelingMainDialog:InitData()
    self._cfData = {self:GetPage1Data(), self:GetPage2Data()}
    self:FillBlackPoints()
end

function UIFeelingMainDialog:FillBlackPoints()
    for i = 1, table.count(self._cfData) do
        local go = self.PageToggleGroup.transform:Find("ToggleCell"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ToggleCell, self.PageToggleGroup)
            go.name = "ToggleCell"..i
        end
        KTool.SetActive(go, true)

        local tog = go.transform:GetComponent("Toggle")
        if tog then
            SetToggleValueChanged(tog, function(value)
                local rect = go.transform:GetComponent(typeof(RectTransform))
                local image = go.transform:GetComponent(typeof(Image))
                if value then
                    image.color = XLuaUtils.HexToColor('#ddfffb')
                    go.transform:GetComponent(typeof(RectTransform)).sizeDelta = Vector2(32, 16)
                else
                    image.color = XLuaUtils.HexToColor('#0ba4a2')
                    go.transform:GetComponent(typeof(RectTransform)).sizeDelta = Vector2(16, 16)
                end
            end)

            if i == 1 then
                tog.isOn = true
            end
        end
    end
end

