function UIFeelingMainDialog:FillEntrys()
    self.PageLoopView:InitListView(#self._cfData, Bind(self, self.OnGetCellByIndex))
    self.PageLoopView.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
end

function UIFeelingMainDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell
    local scr
    --第一页特殊
    if index == 0 then
        cell = listView:NewListViewItem("Page1")
        scr = CfUtils.GetLuaScr(cell, UIFeelingMainItemFirstNode)
    else
        cell = listView:NewListViewItem("Page2")
        scr = CfUtils.GetLuaScr(cell, UIFeelingMainItemSecondNode)
    end

    local data = self._cfData[index + 1]
    if scr then
        scr:Refresh(data)
    end
    return cell
end

function UIFeelingMainDialog:OnSnapNearestChanged(listView, item)
    local ind = self.PageLoopView.CurSnapNearestItemIndex
    local go = self.PageToggleGroup.transform:Find("ToggleCell"..ind + 1)
    if go then
        local tog = go.transform:GetComponent("Toggle")
        tog.isOn = true
    end
end

function UIFeelingMainDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local id = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
        if not isNull(id) then
            ---@type SceneInstance
            local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(id)
            if not isNull(sceneInstance) then
                local roleObject = sceneInstance:GetCacheObjectByName(Constants.MainHomeRoleNodeName)
                if not isNull(roleObject) then
                    KTool.SetActive(roleObject, false)
                end
            end
        end
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, true)
        KTool.SetActive(self.PageLoopView, true)

        cs_coroutine.start(function()
            local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
            blocker:AddCondition("MainChapterEntry")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(CfUtils.GetAnimatorTime(self.Root, "FeelingMainRoot")))
            blocker:RemoveCondition("MainChapterEntry")
        end)
    end))
    return coWait
end

function UIFeelingMainDialog:ClearTimeDown()
    if self.__updateHandle then
        MonoHelper.RemoveUpdateListener(self.__updateHandle)
        self.__updateHandle = nil
    end
end

function UIFeelingMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(false, false)
    end))
    return coWait
end

function UIFeelingMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:ClearTimeDown()
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneReward)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneMessage)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneInvestigate)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneAchievement)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Friend)

        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingMainDialog
